add([(1811,'statement','Same physical contact point under different orientations.','premise'),(1812,'statement','Record differing orientations and compute flange-relative XYZ.','premise')],'pivot-equation','Pivot calibration equation','Let p be the fixed flange-frame TCP point, R_i and t_i the measured flange pose in the base, and c the fixed base-frame contact point. Which relation holds at each ideal contact?', [('R_i p+t_i=c.','Rotate the flange-relative tool offset into the base and add the flange-origin position.'),('R_i c+t_i=p.','This swaps the known frame roles of p and c.'),('R_i p=c+t_i.','This reverses the translation sign.'),('p+t_i=c for every orientation.','This omits rotation of the tool offset.')],typ='derivation',forms=[Ftcp],assumptions=['Added explicit rigid-transform notation; ideal exact contact.'])
add([(1811,'statement','Four distinct tool orientations at a common reference point.','premise')],'pivot-calc','Solve a planar pivot example','In an added planar analogue, R1=I, t1=(8,4) mm; R2 is +90° counterclockwise and t2=(11,3) mm. Both poses contact the same unknown fixed point. What is the tool offset p?', [('(2,1) mm.','Equating p+(8,4) with R2 p+(11,3) gives px+py=3 and py−px=−1.'),('(1,2) mm.','Swapping components does not satisfy both contact equations.'),('(3,−1) mm.','This is t2−t1, before solving the rotation-dependent equation.'),('(−2,−1) mm.','This reverses the solved tool offset.')],typ='numerical',difficulty='medium',forms=[Ftcp],steps=['R2(px,py)=(−py,px).','Equate the two base-frame contact coordinates.','Solve px+py=3 and py−px=−1 to get p=(2,1); c=(10,5).'],assumptions=['Added 2D analogue with exact poses; lengths in mm.'])
